import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import {
  recordEvent,
  replayEvents,
  isDatabaseStale,
  getDatabase,
  insertNode,
  createTestContext,
  Node,
  HiveContext,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}
async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('replayEvents watermark under a transient git failure', () => {
  it('records the real HEAD as the watermark after a full replay of a healthy branch, so the db reports fresh once git recovers', async () => {
    const { ctx } = await bootstrap();
    await addNode(ctx, 'healthy node');

    // Inject exactly ONE transient git failure (index.lock contention) that
    // lands on getCurrentHeadHash (event-store.ts:285 -> 568) during the full
    // replay, then let git recover for every subsequent call.
    const original = ctx.git.getCommitHash.bind(ctx.git);
    let failed = false;
    ctx.git.getCommitHash = (async (...args: any[]) => {
      if (!failed) {
        failed = true;
        throw new Error('fatal: Unable to create index.lock: File exists');
      }
      return (original as any)(...args);
    }) as any;

    // Full replay of a healthy branch. getCurrentHeadHash swallows the
    // transient error into '' (line 571); the branch rows are DELETEd
    // (294-297) and the watermark is written from currentHeadHash (line 310).
    await replayEvents(ctx, branch, true);

    // Git has recovered. A healthy branch that was just fully replayed must
    // report FRESH. It only reports stale if the transient '' was persisted
    // as the watermark (getLastSyncHash then reads it back as null).
    const stale = await isDatabaseStale(ctx, branch);
    expect(stale).toBe(false);
  });
});
